import type {Copy} from './content';
import {money,prices} from './pricing';

// Self-contained answer under the hero of each department and industry page [ru, en, ka]:
// what AI does there in Georgia, integrations (examples, checked per project), control
// and the pilot metric. Written to be quoted by AI search as a whole passage.
// `cost` answers "How much does it cost" in the page FAQ (and FAQPage markup): price, pilot length
// and what the pilot covers on this page. The price lives only there, so a page names it once.
// Prices come from lib/pricing.ts.
type P=keyof typeof prices;
const commas=(n:number)=>String(n).replace(/\B(?=(\d{3})+(?!\d))/g,',');
const ru=(k:P)=>money(prices[k],'gel')+' ('+money(prices[k],'usd')+')';
const en=(k:P)=>commas(prices[k].gel)+' ₾ ($'+commas(prices[k].usd)+')';
const ka=(k:P)=>money(prices[k],'gel')+'‑დან ('+money(prices[k],'usd')+')';
export const detailAnswers:Record<string,{q:Copy;a:Copy;cost:Copy}>={
 sales:{
  cost:[`Пилот в продажах стоит от ${ru('implementation')} и идёт 2–4 недели. В него входят один канал заявок, например WhatsApp или сайт, вопросы для квалификации по вашему скрипту и сделка в CRM с резюме переписки. Разбор звонков по записям телефонии считаем разработкой, от ${ru('development')}, а подготовку КП по прайсу добавляем после пилота, если он достиг метрики.`,
   `A sales pilot starts at ${en('implementation')} and takes 2–4 weeks. It covers one enquiry channel, such as WhatsApp or your website, qualifying questions from your script, and a deal in your CRM with a chat summary. Call analysis from your phone system’s recordings is custom development, from ${en('development')}, and proposal drafting from your price list can be added once the pilot hits its metric.`,
   `გაყიდვების პილოტი ღირს ${ka('implementation')} და 2–4 კვირა გრძელდება. მასში შედის მოთხოვნების ერთი არხი, მაგალითად WhatsApp ან საიტი, კვალიფიკაციის კითხვები თქვენი სკრიპტით და გარიგება CRM‑ში მიმოწერის შეჯამებით. ზარების ანალიზს ტელეფონიის ჩანაწერებით ინდივიდუალურ შემუშავებად ვითვლით, ${ka('development')}. შეთავაზების მომზადებას ფასების სიით პილოტის შემდეგ ვამატებთ, თუ პილოტმა მეტრიკას მიაღწია.`],
  q:['Что ИИ делает в отделе продаж?','What does AI do for a sales team?','რას აკეთებს AI გაყიდვების განყოფილებაში?'],
  a:['ИИ-ассистент отвечает на заявки в WhatsApp, Telegram и на сайте за секунды, на грузинском, английском или русском. Он уточняет задачу, объём, бюджет и сроки, создаёт сделку в CRM (например, amoCRM, Bitrix24 или HubSpot) и передаёт менеджеру тёплого клиента с резюме переписки. Ночью и в выходные заявки не теряются, а утром менеджер видит готовый список. Скидки и условия ассистент берёт только из ваших правил, сделку ведёт человек. Результат измеряем по времени первого ответа, полноте карточек в CRM и доле заявок, дошедших до встречи.',
   'An AI assistant replies to enquiries on WhatsApp, Telegram and your website within seconds, in Georgian, English or Russian. It clarifies the need, quantity, budget and timing, creates a deal in your CRM (for example amoCRM, Bitrix24 or HubSpot) and hands a warm lead to a manager with a summary of the chat. Leads that arrive at night or at weekends are no longer lost, and the team starts the morning with a ready list. Discounts and terms come only from your rules, and a person runs the deal. We measure first response time, CRM completeness and the share of enquiries that reach a meeting.',
   'AI ასისტენტი WhatsApp‑ში, Telegram‑სა და საიტზე წამებში პასუხობს მოთხოვნებს ქართულად, ინგლისურად ან რუსულად. ის აზუსტებს საჭიროებას, მოცულობას, ბიუჯეტსა და ვადებს, ქმნის გარიგებას CRM‑ში (მაგალითად, amoCRM‑ში, Bitrix24‑ში ან HubSpot‑ში) და თბილ კლიენტს მენეჯერს მიმოწერის შეჯამებით გადასცემს. ღამით და შაბათ‑კვირას მოთხოვნები აღარ იკარგება, დილით კი მენეჯერი მზა სიას ხედავს. ფასდაკლებებსა და პირობებს ასისტენტი მხოლოდ თქვენი წესებიდან იღებს, გარიგებას ადამიანი წარმართავს. შედეგს ვზომავთ პირველი პასუხის დროით, CRM‑ის სისრულითა და შეხვედრამდე მისული მოთხოვნების წილით.']
 },
 marketing:{
  cost:[`Начать можно с обучения команды, от ${ru('training')}: сотрудники учатся готовить черновики с ИИ по вашему брендбуку. Внедрение стоит от ${ru('implementation')}, пилот занимает 2–4 недели. В него входят инструкции с правилами бренда и адаптация одного материала под ваши каналы и три языка. Утреннюю сводку из Meta Ads и Google Analytics считаем разработкой, от ${ru('development')}.`,
   `You can start with team training, from ${en('training')}: staff learn to draft with AI from your brand book. Implementation starts at ${en('implementation')}, with a 2–4 week pilot. It includes instructions built on your brand rules and adapting one piece of content to your channels and three languages. A morning summary from Meta Ads and Google Analytics is custom development, from ${en('development')}.`,
   `დაწყება შეიძლება გუნდის სწავლებით, ${ka('training')}: თანამშრომლები სწავლობენ AI‑ით მონახაზების მომზადებას თქვენი ბრენდბუქით. დანერგვა ღირს ${ka('implementation')}, პილოტი 2–4 კვირა გრძელდება. მასში შედის ინსტრუქციები ბრენდის წესებით და ერთი მასალის მორგება თქვენს არხებსა და სამ ენას. დილის შეჯამებას Meta Ads‑იდან და Google Analytics‑იდან ინდივიდუალურ შემუშავებად ვითვლით, ${ka('development')}.`],
  q:['Что ИИ делает в маркетинге?','What does AI do for marketing?','რას აკეთებს AI მარკეტინგში?'],
  a:['ИИ готовит черновики постов, рассылок, описаний и рекламных текстов по вашему брендбуку и сразу адаптирует их под каналы и три языка: грузинский, английский и русский. Каждое утро он собирает сводку по кампаниям из рекламных кабинетов и аналитики (например, Meta и Google Analytics), а один материал превращает в версии для сайта, соцсетей и email. Правила бренда, запретные слова и обращение к клиенту фиксируем заранее. Публикует всегда человек. Результат измеряем по времени выпуска материала, числу правок и соблюдению требований бренда.',
   'AI drafts posts, newsletters, product descriptions and ad copy from your brand book and adapts them to each channel and to Georgian, English and Russian. Every morning it compiles a campaign summary from your ad accounts and analytics (for example Meta and Google Analytics), and turns one piece of content into versions for the website, social media and email. Brand rules, banned words and the way you address customers are agreed upfront, and a person always publishes. We measure production time, the number of revisions and brand compliance.',
   'AI ამზადებს პოსტების, გზავნილების, აღწერებისა და სარეკლამო ტექსტების მონახაზებს თქვენი ბრენდბუქით და მაშინვე არგებს მათ არხებსა და სამ ენას: ქართულს, ინგლისურსა და რუსულს. ყოველ დილით ის აგროვებს კამპანიების შეჯამებას სარეკლამო კაბინეტებიდან და ანალიტიკიდან (მაგალითად, Meta‑დან და Google Analytics‑იდან), ერთ მასალას კი საიტის, სოციალური ქსელებისა და ელფოსტის ვერსიებად აქცევს. ბრენდის წესებს, აკრძალულ სიტყვებსა და კლიენტისადმი მიმართვას წინასწარ ვაფიქსირებთ. აქვეყნებს ყოველთვის ადამიანი. შედეგს ვზომავთ მასალის მომზადების დროით, შესწორებების რაოდენობითა და ბრენდის მოთხოვნების დაცვით.']
 },
 support:{
  cost:[`Поддержку запускаем пилотом на реальных обращениях: 2–4 недели, от ${ru('implementation')}. В цену входят сборка базы знаний из ваших регламентов и прошлых диалогов, один канал (WhatsApp, Telegram или сайт) и правила передачи оператору. Ответы меняются вместе с ценами и правилами, поэтому обновление базы можно передать нам как дополнительное ведение, от ${ru('support')} в месяц.`,
   `Support starts with a pilot on real conversations: 2–4 weeks, from ${en('implementation')}. The price covers building a knowledge base from your policies and past chats, one channel (WhatsApp, Telegram or your website) and hand-off rules for agents. Answers change as your prices and rules change, so you can leave knowledge base updates to us as ongoing maintenance, from ${en('support')} a month.`,
   `მხარდაჭერას რეალურ მიმართვებზე პილოტით ვიწყებთ: 2–4 კვირა, ${ka('implementation')}. ფასში შედის ცოდნის ბაზის აწყობა თქვენი რეგლამენტებიდან და წინა დიალოგებიდან, ერთი არხი (WhatsApp, Telegram ან საიტი) და ოპერატორზე გადაცემის წესები. პასუხები ფასებთან და წესებთან ერთად იცვლება, ამიტომ ბაზის განახლება შეგიძლიათ დამატებით მომსახურებად გადმოგვცეთ, ${ka('support')} თვეში.`],
  q:['Что ИИ делает в поддержке клиентов?','What does AI do for customer support?','რას აკეთებს AI მომხმარებელთა მხარდაჭერაში?'],
  a:['Чат-бот отвечает клиентам в WhatsApp, Telegram и на сайте круглосуточно, на грузинском, английском и русском, и берёт ответы только из вашей базы знаний: цены, доставка, статусы, правила возврата. Если ответа в базе нет или клиент недоволен, диалог сразу переходит к оператору вместе с историей, и клиенту не нужно повторять вопрос. Операторам ассистент предлагает черновики ответов и сам распределяет обращения по темам в helpdesk (например, Zendesk, Intercom или Jivo). Голосовые сообщения он расшифровывает и отвечает текстом. Результат измеряем по времени ответа, точности и доле передач оператору.',
   'The chatbot answers customers on WhatsApp, Telegram and your website around the clock, in Georgian, English and Russian, using only your knowledge base: prices, delivery, order status and return rules. When the answer is not in the base or a customer is unhappy, the chat moves to an agent with the full history, so the customer does not repeat the question. For agents, the assistant drafts replies and routes tickets by topic in your helpdesk (for example Zendesk, Intercom or Jivo). It transcribes voice messages and replies in text. We measure response time, accuracy and the share of chats handed to an agent.',
   'ჩატბოტი კლიენტებს WhatsApp‑ში, Telegram‑სა და საიტზე დღე‑ღამის განმავლობაში პასუხობს ქართულად, ინგლისურად და რუსულად და პასუხებს მხოლოდ თქვენი ცოდნის ბაზიდან იღებს: ფასები, მიწოდება, სტატუსები, დაბრუნების წესები. თუ პასუხი ბაზაში არ არის ან კლიენტი უკმაყოფილოა, საუბარი მაშინვე ოპერატორს ისტორიასთან ერთად გადაეცემა და კლიენტს კითხვის გამეორება არ უწევს. ოპერატორებს ასისტენტი პასუხების მონახაზებს სთავაზობს და მიმართვებს თემების მიხედვით ანაწილებს helpdesk‑ში (მაგალითად, Zendesk‑ში, Intercom‑ში ან Jivo‑ში). ხმოვან შეტყობინებებს შიფრავს და ტექსტით პასუხობს. შედეგს ვზომავთ პასუხის დროით, სიზუსტითა და ოპერატორზე გადაცემის წილით.']
 },
 operations:{
  cost:[`Внедрение в бэк-офисе стоит от ${ru('implementation')}, пилот — 2–4 недели. Для пилота выбираем один из трёх сценариев: извлечение данных из одного типа документов, разбор общего почтового ящика по ответственным или внутренний ассистент по регламентам. Прямая запись данных в 1С или ERP — это разработка, от ${ru('development')}.`,
   `Back-office implementation starts at ${en('implementation')}, with a 2–4 week pilot. For the pilot we pick one of three workflows: data extraction from one document type, sorting a shared inbox by owner, or an internal assistant that answers from your policies. Writing data straight into 1C or an ERP is custom development, from ${en('development')}.`,
   `ბექ‑ოფისში დანერგვა ღირს ${ka('implementation')}, პილოტი 2–4 კვირა გრძელდება. პილოტისთვის სამი სცენარიდან ერთს ვირჩევთ: მონაცემების ამოღება დოკუმენტის ერთი ტიპიდან, საერთო ფოსტის განაწილება პასუხისმგებლებზე ან შიდა ასისტენტი, რომელიც თქვენი რეგლამენტებით პასუხობს. მონაცემების პირდაპირ 1C‑ში ან ERP‑ში ჩაწერა ინდივიდუალური შემუშავებაა, ${ka('development')}.`],
  q:['Что ИИ делает в бэк-офисе?','What does AI do for back-office operations?','რას აკეთებს AI ბექ‑ოფისში?'],
  a:['ИИ извлекает данные из PDF, сканов, писем и форм, раскладывает их по полям и передаёт в вашу систему: 1С, ERP, CRM или Google Workspace. Входящие письма и заявки он распределяет по ответственным, а внутренний ассистент отвечает сотрудникам по регламентам и находит нужный документ. Если ИИ не уверен в значении, поле подсвечивается и уходит человеку на подтверждение. Требования к коммерческой тайне и персональным данным фиксируем до старта, данные не используются для обучения публичных моделей. Результат измеряем по времени обработки, числу возвратов на исправление и ручных действий.',
   'AI extracts data from PDFs, scans, emails and forms, maps it to fields and sends it to your system: 1C, an ERP, a CRM or Google Workspace. It routes incoming emails and requests to the right owners, and an internal assistant answers staff questions from your policies and finds the right document. When AI is unsure about a value, the field is highlighted and goes to a person for confirmation. Trade-secret and personal-data rules are agreed before we start, and your data is not used to train public models. We measure processing time, rework and manual steps.',
   'AI იღებს მონაცემებს PDF‑ებიდან, სკანებიდან, წერილებიდან და ფორმებიდან, ანაწილებს ველებად და გადასცემს თქვენს სისტემას: 1C‑ს, ERP‑ს, CRM‑ს ან Google Workspace‑ს. შემოსულ წერილებსა და მოთხოვნებს პასუხისმგებლებზე ანაწილებს, შიდა ასისტენტი კი თანამშრომლებს წესების მიხედვით პასუხობს და საჭირო დოკუმენტს პოულობს. თუ AI მნიშვნელობაში დარწმუნებული არ არის, ველი მოინიშნება და ადამიანს დასადასტურებლად გადაეცემა. კომერციული საიდუმლოებისა და პერსონალური მონაცემების მოთხოვნებს დაწყებამდე ვაფიქსირებთ, მონაცემები საჯარო მოდელების სწავლებისთვის არ გამოიყენება. შედეგს ვზომავთ დამუშავების დროით, შესასწორებლად დაბრუნებებითა და ხელით შესრულებული ქმედებებით.']
 },
 hr:{
  cost:[`Корпоративный HR-ассистент на вашей базе знаний стоит от ${ru('implementation')}, пилот на одном отделе — 2–4 недели. В пилот входят загрузка регламентов, настройка доступа по ролям и бот в мессенджере вашей команды. Подключение к HR-системе или LMS считаем разработкой, от ${ru('development')}.`,
   `A company HR assistant on your knowledge base starts at ${en('implementation')}, and a pilot in one department takes 2–4 weeks. The pilot covers loading your policies, role-based access and a bot in your team’s messenger. Connecting an HR system or LMS is priced as custom development, from ${en('development')}.`,
   `კორპორატიული HR ასისტენტი თქვენს ცოდნის ბაზაზე ღირს ${ka('implementation')}, პილოტი ერთ განყოფილებაზე 2–4 კვირა გრძელდება. პილოტში შედის რეგლამენტების ატვირთვა, როლების მიხედვით წვდომის მორგება და ბოტი თქვენი გუნდის მესენჯერში. HR სისტემასთან ან LMS‑თან დაკავშირებას ინდივიდუალურ შემუშავებად ვითვლით, ${ka('development')}.`],
  q:['Что ИИ делает в HR?','What does AI do for HR?','რას აკეთებს AI HR‑ში?'],
  a:['Корпоративный ИИ-ассистент отвечает сотрудникам на вопросы по внутренним правилам: отпуска, командировки, документы, доступы. Он работает в привычном мессенджере, например Slack, Microsoft Teams или Telegram, и ссылается на конкретный регламент. Для новичков он собирает трек адаптации под роль и готовит учебные материалы и тесты из ваших инструкций. Доступ настраивается по ролям: стажёр не увидит данные о зарплатах. Внутренние документы используются только в вашем решении. Результат измеряем по времени поиска ответа, освоению сценариев и обратной связи сотрудников.',
   'A company AI assistant answers employees’ questions about internal rules: leave, business trips, documents and access. It works in the messenger your team already uses, such as Slack, Microsoft Teams or Telegram, and cites the exact policy. For new hires it builds a role-based onboarding track and prepares training materials and quizzes from your instructions. Access is role-based, so an intern cannot see salary data, and internal documents are used only inside your solution. We measure time to find answers, scenario adoption and employee feedback.',
   'კორპორატიული AI ასისტენტი თანამშრომლებს შიდა წესებზე პასუხობს: შვებულება, მივლინება, დოკუმენტები, წვდომები. ის მუშაობს ნაცნობ მესენჯერში, მაგალითად Slack‑ში, Microsoft Teams‑ში ან Telegram‑ში, და კონკრეტულ წესზე მიუთითებს. ახალი თანამშრომლებისთვის როლის მიხედვით ადაპტაციის გეგმას ადგენს და თქვენი ინსტრუქციებიდან სასწავლო მასალებსა და ტესტებს ამზადებს. წვდომა როლების მიხედვით იმართება: სტაჟიორი ხელფასების მონაცემებს ვერ ნახავს. შიდა დოკუმენტები მხოლოდ თქვენს გადაწყვეტაში გამოიყენება. შედეგს ვზომავთ პასუხის ძიების დროით, სცენარების ათვისებითა და თანამშრომლების უკუკავშირით.']
 },
 finance:{
  cost:[`В бухгалтерии пилот идёт 2–4 недели на одном типе документов, например на счетах поставщиков или чеках сотрудников, и стоит от ${ru('implementation')}. В него входят распознавание реквизитов, сумм и НДС, подсветка нечётких полей и выгрузка черновиков в таблицу для проверки. Если черновики должны создаваться прямо в 1С, способ обмена выбираем под вашу конфигурацию, и это разработка от ${ru('development')}.`,
   `In accounting, the pilot runs for 2–4 weeks on one document type, such as supplier invoices or staff receipts, and starts at ${en('implementation')}. It covers reading company details, amounts and VAT, flagging unclear fields and exporting drafts to a spreadsheet for review. If drafts must be created directly in 1C, we choose the exchange method for your configuration, and this is custom development from ${en('development')}.`,
   `ბუღალტერიის პილოტი ღირს ${ka('implementation')} და 2–4 კვირა გრძელდება დოკუმენტის ერთ ტიპზე, მაგალითად მომწოდებლების ინვოისებზე ან თანამშრომლების ჩეკებზე. მასში შედის რეკვიზიტების, თანხებისა და დღგ‑ს ამოცნობა, ბუნდოვანი ველების მონიშვნა და მონახაზების გადატანა ცხრილში შესამოწმებლად. თუ მონახაზები პირდაპირ 1C‑ში უნდა შეიქმნას, გაცვლის ვარიანტს თქვენი კონფიგურაციით ვარჩევთ და ეს ინდივიდუალური შემუშავებაა, ${ka('development')}.`],
  q:['Что ИИ делает в бухгалтерии?','What does AI do for accounting?','რას აკეთებს AI ბუღალტერიაში?'],
  a:['ИИ извлекает реквизиты, суммы и НДС из счетов, актов, накладных и чеков, даже из плохих сканов, и готовит черновики документов в учётной системе, например в 1С или SAP. Он сверяет взаиморасчёты с контрагентами по выпискам и подсвечивает расхождения, а чеки сотрудников превращает в черновик авансового отчёта. Документы ИИ не проводит: проводит бухгалтер, а нечёткие значения требуют его подтверждения. Данные остаются в вашем контуре и не используются для обучения публичных моделей. Результат измеряем по времени обработки, числу ошибок и объёму ручной сверки.',
   'AI extracts company details, amounts and VAT from invoices, acts, delivery notes and receipts, even poor scans, and prepares draft documents in your accounting system, for example 1C or SAP. It reconciles balances with counterparties from bank statements and highlights mismatches, and turns staff receipts into a draft expense report. AI does not post documents: an accountant does, and unclear values need their confirmation. Data stays within your environment and is not used to train public models. We measure processing time, errors and the amount of manual reconciliation.',
   'AI იღებს რეკვიზიტებს, თანხებსა და დღგ‑ს ინვოისებიდან, აქტებიდან, ზედნადებებიდან და ჩეკებიდან, ცუდი სკანებიდანაც კი, და ამზადებს დოკუმენტების მონახაზებს სააღრიცხვო სისტემაში, მაგალითად 1C‑ში ან SAP‑ში. ის ამონაწერებით ადარებს ანგარიშსწორებას კონტრაგენტებთან და მონიშნავს შეუსაბამობებს, თანამშრომლების ჩეკებს კი საავანსო ანგარიშის მონახაზად აქცევს. დოკუმენტებს AI არ ატარებს: ატარებს ბუღალტერი, ბუნდოვანი მნიშვნელობები კი მის დადასტურებას საჭიროებს. მონაცემები თქვენს გარემოში რჩება და საჯარო მოდელების სწავლებისთვის არ გამოიყენება. შედეგს ვზომავთ დამუშავების დროით, შეცდომების რაოდენობითა და ხელით შედარების მოცულობით.']
 },
 procurement:{
  cost:[`Пилот в закупках идёт на одной категории товаров: 2–4 недели, от ${ru('implementation')}. ИИ разбирает КП поставщиков этой категории из PDF, Excel и писем и собирает сравнительную таблицу по вашим критериям: цена за единицу, срок, условия оплаты. Передача таблиц и черновиков заказов в 1С или SAP — разработка, от ${ru('development')}.`,
   `A procurement pilot runs on one purchasing category: 2–4 weeks, from ${en('implementation')}. AI reads that category’s supplier quotes from PDFs, spreadsheets and emails and builds a comparison table against your criteria: unit price, lead time and payment terms. Sending tables and draft orders to 1C or SAP is custom development, from ${en('development')}.`,
   `შესყიდვების პილოტი პროდუქციის ერთ კატეგორიაზე ტარდება: 2–4 კვირა, ${ka('implementation')}. AI ამ კატეგორიის მომწოდებლების შეთავაზებებს PDF‑ებიდან, Excel‑იდან და წერილებიდან ამუშავებს და თქვენი კრიტერიუმებით შედარების ცხრილს ადგენს: ერთეულის ფასი, ვადა, გადახდის პირობები. ცხრილებისა და შეკვეთის მონახაზების გადაცემა 1C‑ში ან SAP‑ში ინდივიდუალური შემუშავებაა, ${ka('development')}.`],
  q:['Что ИИ делает в закупках?','What does AI do for procurement?','რას აკეთებს AI შესყიდვებში?'],
  a:['ИИ извлекает цены, сроки поставки и условия оплаты из коммерческих предложений в PDF, Excel и письмах, приводит их к единым единицам и собирает сравнительную таблицу с рейтингом поставщиков. Он сверяет спецификации, счета и договоры, подсвечивает расхождения в цене, количестве и условиях и готовит вопросы поставщику, если чего-то не хватает. Статусы поставок обновляются из писем перевозчиков. Заказы ИИ не размещает: решение принимает менеджер, а правила тендерной политики задаются заранее. Результат измеряем по времени сравнения, полноте условий и числу исправлений.',
   'AI extracts prices, lead times and payment terms from supplier quotes in PDFs, spreadsheets and emails, normalises units and builds a comparison table with a supplier ranking. It checks specifications, invoices and contracts, flags price, quantity and term mismatches, and drafts questions to suppliers when something is missing. Delivery statuses update from carrier emails. AI does not place orders: a manager decides, and your tender policy rules are set upfront. We measure comparison time, completeness of terms and the number of corrections.',
   'AI იღებს ფასებს, მიწოდების ვადებსა და გადახდის პირობებს კომერციული შეთავაზებებიდან PDF‑ში, Excel‑სა და წერილებში, ერთიან ერთეულებზე გადაჰყავს და მომწოდებლების რეიტინგით შედარების ცხრილს ადგენს. ის ადარებს სპეციფიკაციებს, ინვოისებსა და ხელშეკრულებებს, მონიშნავს შეუსაბამობებს ფასში, რაოდენობასა და პირობებში და თუ რამე აკლია, მომწოდებლისთვის კითხვებს ამზადებს. მიწოდების სტატუსები გადამზიდავების წერილებიდან ახლდება. შეკვეთებს AI არ აფორმებს: გადაწყვეტილებას მენეჯერი იღებს, სატენდერო პოლიტიკის წესები კი წინასწარ განისაზღვრება. შედეგს ვზომავთ შედარების დროით, პირობების სისრულითა და შესწორებების რაოდენობით.']
 },
 leadership:{
  cost:[`Аудит, с которого начинается стратегия, бесплатный. Обучение руководителей и команды стоит от ${ru('training')}. Первый пилот — от ${ru('implementation')} и 2–4 недели на одном процессе. Если процессу нужны свои интеграции, разработка начинается от ${ru('development')}.`,
   `The audit that starts the strategy is free. Training for managers and the team starts at ${en('training')}. The first pilot starts at ${en('implementation')} and takes 2–4 weeks on one workflow. If the workflow needs its own integrations, custom development starts at ${en('development')}.`,
   `აუდიტი, რომლითაც სტრატეგია იწყება, უფასოა. ხელმძღვანელებისა და გუნდის სწავლება ღირს ${ka('training')}. პირველი პილოტი ღირს ${ka('implementation')} და 2–4 კვირა გრძელდება ერთ პროცესზე. თუ პროცესს საკუთარი ინტეგრაციები სჭირდება, ინდივიდუალური შემუშავება ღირს ${ka('development')}.`],
  q:['С чего начать внедрение ИИ в компании?','Where should a company start with AI?','საიდან დავიწყოთ AI‑ს დანერგვა კომპანიაში?'],
  a:['Начинать стоит с одного процесса, где много повторяющейся работы и есть понятная метрика: заявки клиентов, ответы в мессенджерах или документы. На бесплатном аудите мы разбираем процессы, считаем эффект в часах и лари и выбираем пилот с самой понятной экономикой. Если проект не окупается, говорим об этом прямо. После пилота на ваших реальных данных решение масштабируется на другие отделы без роста штата. Руководитель получает сводки по ключевым показателям в привычном канале, например в Telegram или Bitrix24. Права на созданные решения и инструкции передаём вам. Результат измеряем по затратам на процесс, времени сотрудников и качеству результата.',
   'Start with one workflow that has a lot of repetitive work and a clear metric: customer enquiries, messenger replies or documents. In a free audit we review your processes, estimate the effect in hours and lari, and choose the pilot with the clearest economics. If a project will not pay back, we say so plainly. After a pilot on your real data, the solution scales to other departments without adding headcount. Leadership gets summaries of key metrics in a familiar channel, for example Telegram or Bitrix24. Rights to the solutions and documentation are handed over to you. We measure process cost, staff time and the quality of the result.',
   'დაწყება ღირს ერთი პროცესით, სადაც ბევრი განმეორებადი სამუშაოა და მკაფიო მეტრიკა: კლიენტების მოთხოვნები, მესენჯერებში პასუხები ან დოკუმენტები. უფასო აუდიტზე ვაანალიზებთ პროცესებს, ვითვლით ეფექტს საათებსა და ლარში და ვირჩევთ პილოტს ყველაზე გასაგები ეკონომიკით. თუ პროექტი არ ანაზღაურდება, ამას პირდაპირ ვამბობთ. თქვენს რეალურ მონაცემებზე პილოტის შემდეგ გადაწყვეტა სხვა განყოფილებებზე ვრცელდება შტატის ზრდის გარეშე. ხელმძღვანელი ძირითადი მაჩვენებლების შეჯამებებს ნაცნობ არხში იღებს, მაგალითად Telegram‑ში ან Bitrix24‑ში. შექმნილ გადაწყვეტებსა და ინსტრუქციებზე უფლებებს თქვენ გადმოგცემთ. შედეგს ვზომავთ პროცესის ხარჯით, თანამშრომლების დროითა და შედეგის ხარისხით.']
 },
 retail:{
  cost:[`Пилот для интернет-магазина стоит от ${ru('implementation')} и занимает 2–4 недели. В него входят загрузка вашего каталога и остатков, консультант в одном канале (Instagram, WhatsApp или сайт) и ответы о доставке и возврате по вашим правилам. Статусы заказов из системы магазина или 1С, напоминания о брошенной корзине и оплату по ссылке в чате подключаем как разработку, от ${ru('development')}, если ваша платформа и эквайринг это поддерживают.`,
   `An online store pilot starts at ${en('implementation')} and takes 2–4 weeks. It includes loading your catalogue and stock, a shopping assistant on one channel (Instagram, WhatsApp or your website) and answers on delivery and returns from your policies. Order status from your store system or 1C, abandoned-cart reminders and payment links in chat are custom development, from ${en('development')}, where your platform and payment provider support them.`,
   `ონლაინ მაღაზიის პილოტი ღირს ${ka('implementation')} და 2–4 კვირა გრძელდება. მასში შედის თქვენი კატალოგისა და მარაგის ატვირთვა, კონსულტანტი ერთ არხზე (Instagram, WhatsApp ან საიტი) და პასუხები მიწოდებასა და დაბრუნებაზე თქვენი წესებით. შეკვეთების სტატუსები მაღაზიის სისტემიდან ან 1C‑იდან, მიტოვებული კალათის შეხსენებები და ჩატში ბმულით გადახდა ინდივიდუალური შემუშავებაა, ${ka('development')}, თუ თქვენი პლატფორმა და ეკვაირინგი ამას მხარს უჭერს.`],
  q:['Что ИИ делает для интернет-магазина?','What does AI do for an online store?','რას აკეთებს AI ონლაინ მაღაზიისთვის?'],
  a:['ИИ-консультант в Instagram, WhatsApp и на сайте подбирает товар по описанию покупателя, проверяет наличие и размеры в вашем каталоге и отвечает на грузинском, английском или русском. Он предлагает сопутствующие позиции, напоминает о брошенной корзине и отвечает на вопрос «где мой заказ» по данным вашей системы, например Shopify, WooCommerce, 1С-Битрикс или RetailCRM. Возвраты и жалобы уходят менеджеру. Ассистент предлагает только товары, которые есть на складе, и не выходит за лимиты скидок. Результат измеряем по времени ответа и доле ответов без исправлений.',
   'An AI shopping assistant on Instagram, WhatsApp and your website finds products from a shopper’s description, checks stock and sizes in your catalogue and replies in Georgian, English or Russian. It suggests related items, follows up on abandoned carts and answers “where is my order” from your system, for example Shopify, WooCommerce, 1C-Bitrix or RetailCRM. Returns and complaints go to a manager. The assistant offers only items that are in stock and stays within your discount limits. We measure response time and the share of replies that need no correction.',
   'AI კონსულტანტი Instagram‑ში, WhatsApp‑სა და საიტზე მყიდველის აღწერით პროდუქტს არჩევს, თქვენს კატალოგში მარაგსა და ზომებს ამოწმებს და ქართულად, ინგლისურად ან რუსულად პასუხობს. ის თანმხლებ პროდუქტებს სთავაზობს, მიტოვებულ კალათაზე შეახსენებს და კითხვას „სად არის ჩემი შეკვეთა“ თქვენი სისტემის მონაცემებით პასუხობს, მაგალითად Shopify‑დან, WooCommerce‑დან, 1C‑Bitrix‑იდან ან RetailCRM‑იდან. დაბრუნებები და საჩივრები მენეჯერს გადაეცემა. ასისტენტი მხოლოდ მარაგში არსებულ პროდუქტს სთავაზობს და ფასდაკლების ლიმიტებს არ სცდება. შედეგს ვზომავთ პასუხის დროითა და შესწორების გარეშე პასუხების წილით.']
 },
 wholesale:{
  cost:[`Для оптовой компании берём один поток заказов, например заявки в Excel из почты. Пилот на нём идёт 2–4 недели и стоит от ${ru('implementation')}. В него входят список синонимов для вашей номенклатуры, разбор заказа в черновик счёта в таблице и передача сомнительных строк менеджеру. Создание счёта прямо в 1С, МойСклад или SAP — разработка, от ${ru('development')}.`,
   `For a wholesaler we take one order flow, such as Excel orders sent by email. The pilot on it takes 2–4 weeks and starts at ${en('implementation')}. It includes a synonym list for your item master, turning each order into a draft invoice in a spreadsheet and passing uncertain lines to a manager. Creating the invoice directly in 1C, MoySklad or SAP is custom development, from ${en('development')}.`,
   `საბითუმო კომპანიისთვის შეკვეთების ერთ ნაკადს ვიღებთ, მაგალითად ფოსტით მოსულ Excel‑შეკვეთებს. პილოტი ამ ნაკადზე 2–4 კვირა გრძელდება და ღირს ${ka('implementation')}. მასში შედის სინონიმების სია თქვენი ნომენკლატურისთვის, შეკვეთიდან ინვოისის მონახაზის მომზადება ცხრილში და საეჭვო ხაზების მენეჯერზე გადაცემა. ინვოისის შექმნა პირდაპირ 1C‑ში, MoySklad‑ში ან SAP‑ში ინდივიდუალური შემუშავებაა, ${ka('development')}.`],
  q:['Что ИИ делает в оптовой торговле?','What does AI do for wholesale and distribution?','რას აკეთებს AI საბითუმო ვაჭრობაში?'],
  a:['ИИ принимает заказы клиентов в любом формате: PDF, Excel, письмо или сообщение в WhatsApp. Он сопоставляет позиции с вашей номенклатурой, даже если клиент называет товар по-своему, и готовит черновик счёта в учётной системе, например в 1С, МойСклад или SAP. Прайсы поставщиков он приводит к единому виду и обновляет, а дилерам отвечает о наличии и ценах в мессенджере. Скидки ИИ даёт только в рамках профиля клиента в вашей системе. Счёт проверяет и отправляет менеджер. Результат измеряем по времени подготовки счёта и числу исправленных позиций.',
   'AI takes customer orders in any format: a PDF, a spreadsheet, an email or a WhatsApp message. It matches line items to your item master, even when customers use their own names for products, and prepares a draft invoice in your accounting system, for example 1C, MoySklad or SAP. It normalises and updates supplier price lists and answers dealers’ stock and price questions in a messenger. Discounts follow only the customer’s profile in your system, and a manager reviews and sends the invoice. We measure invoice preparation time and the number of corrected line items.',
   'AI კლიენტების შეკვეთებს ნებისმიერ ფორმატში იღებს: PDF, Excel, წერილი ან შეტყობინება WhatsApp‑ში. ის პოზიციებს თქვენს ნომენკლატურას უთანადებს, მაშინაც კი, როცა კლიენტი პროდუქტს თავისებურად უწოდებს, და ინვოისის მონახაზს სააღრიცხვო სისტემაში ამზადებს, მაგალითად 1C‑ში, MoySklad‑ში ან SAP‑ში. მომწოდებლების ფასების სიებს ერთ ფორმაზე გადაჰყავს და ანახლებს, დილერებს კი მარაგსა და ფასებზე მესენჯერში პასუხობს. ფასდაკლებას AI მხოლოდ თქვენს სისტემაში კლიენტის პროფილის ფარგლებში აძლევს. ინვოისს მენეჯერი ამოწმებს და აგზავნის. შედეგს ვზომავთ ინვოისის მომზადების დროითა და შესწორებული პოზიციების რაოდენობით.']
 },
 hotels:{
  cost:[`ИИ-консьерж для отеля стоит от ${ru('implementation')}, пилот — 2–4 недели. В пилот входят ответы гостям по вашим правилам проживания в WhatsApp или Instagram и передача администратору запросов на бронирование и жалоб. Проверка свободных номеров в PMS и прямое бронирование со ссылкой на оплату — разработка, от ${ru('development')}, если ваша система бронирования открывает доступ по API.`,
   `An AI concierge for a hotel starts at ${en('implementation')}, with a 2–4 week pilot. The pilot covers answers to guests from your house rules on WhatsApp or Instagram, with booking requests and complaints passed to reception. Availability checks in your PMS and direct bookings with a payment link are custom development, from ${en('development')}, if your booking system offers API access.`,
   `სასტუმროს AI კონსიერჟი ღირს ${ka('implementation')}, პილოტი 2–4 კვირა გრძელდება. პილოტში შედის სტუმრებისთვის პასუხები თქვენი სასტუმროს წესებით WhatsApp‑ში ან Instagram‑ში და დაჯავშნის მოთხოვნებისა და საჩივრების ადმინისტრატორზე გადაცემა. თავისუფალი ნომრების შემოწმება PMS‑ში და პირდაპირი ჯავშანი გადახდის ბმულით ინდივიდუალური შემუშავებაა, ${ka('development')}, თუ თქვენი დაჯავშნის სისტემა API‑ით წვდომას იძლევა.`],
  q:['Что ИИ делает для отеля?','What does AI do for a hotel?','რას აკეთებს AI სასტუმროსთვის?'],
  a:['ИИ-консьерж отвечает гостям в WhatsApp, Instagram и на сайте круглосуточно и на языке гостя: грузинском, английском, русском и других. Он рассказывает о завтраках, трансферах, парковке и правилах заселения, проверяет свободные номера в вашей PMS (например, Opera, Cloudbeds, Bnovo или TravelLine) и принимает прямые бронирования без комиссии площадок. После выезда он просит оставить отзыв. Занятый номер ассистент не предложит, политику отмены соблюдает, а жалобы сразу передаёт администратору. Для отелей Аджарии и Тбилиси межсезонье — удобное время, чтобы настроить ассистента до сезона. Результат измеряем по времени ответа и числу вопросов, где понадобился администратор.',
   'An AI concierge answers guests on WhatsApp, Instagram and your website around the clock and in the guest’s language: Georgian, English, Russian and others. It explains breakfast, transfers, parking and check-in rules, checks availability in your PMS (for example Opera, Cloudbeds, Bnovo or TravelLine) and takes direct bookings without platform commissions. After check-out it asks for a review. The assistant never offers an occupied room, follows your cancellation policy and passes complaints straight to reception. For hotels in Adjara and Tbilisi, the off-season is a good time to set it up before the next season. We measure response time and how many questions needed reception.',
   'AI კონსიერჟი სტუმრებს WhatsApp‑ში, Instagram‑სა და საიტზე დღე‑ღამის განმავლობაში სტუმრის ენაზე პასუხობს: ქართულად, ინგლისურად, რუსულად და სხვა ენებზე. ის ყვება საუზმეზე, ტრანსფერზე, პარკინგსა და შესახლების წესებზე, თავისუფალ ნომრებს თქვენს PMS‑ში ამოწმებს (მაგალითად, Opera‑ში, Cloudbeds‑ში, Bnovo‑ში ან TravelLine‑ში) და პირდაპირ ჯავშნებს პლატფორმების საკომისიოს გარეშე იღებს. გაწერის შემდეგ შეფასების დატოვებას სთხოვს. დაკავებულ ნომერს ასისტენტი არ შესთავაზებს, გაუქმების პოლიტიკას იცავს, საჩივრებს კი მაშინვე ადმინისტრატორს გადასცემს. აჭარისა და თბილისის სასტუმროებისთვის არასეზონი მოსახერხებელი დროა ასისტენტის სეზონამდე მოსამზადებლად. შედეგს ვზომავთ პასუხის დროითა და იმ კითხვების რაოდენობით, სადაც ადმინისტრატორი დასჭირდა.']
 },
 tourism:{
  cost:[`Туроператору пилот обойдётся от ${ru('implementation')}, срок — 2–4 недели. В него входят сбор брифа туриста в WhatsApp, Telegram или на сайте и черновик программы для менеджера из вашей базы отелей, гидов и транспорта. База может оставаться в Google Таблицах, отдельная система для пилота не нужна. Автоматический расчёт сметы по вашим тарифам и марже — разработка, от ${ru('development')}, а консьержа на маршруте можно подключить после пилота.`,
   `For a tour operator, the pilot starts at ${en('implementation')} and takes 2–4 weeks. It covers collecting the traveller’s brief on WhatsApp, Telegram or your website and a draft itinerary for a manager from your base of hotels, guides and transport. That base can stay in Google Sheets, and the pilot needs no separate system. Automatic cost estimates from your rates and margin are custom development, from ${en('development')}, and the on-trip concierge can be added after the pilot.`,
   `ტუროპერატორის პილოტი ღირს ${ka('implementation')} და 2–4 კვირა გრძელდება. მასში შედის ტურისტის ბრიფის შეგროვება WhatsApp‑ში, Telegram‑ში ან საიტზე და პროგრამის მონახაზი მენეჯერისთვის თქვენი სასტუმროების, გიდებისა და ტრანსპორტის ბაზიდან. ბაზა შეიძლება Google Sheets‑ში დარჩეს, პილოტს ცალკე სისტემა არ სჭირდება. ხარჯთაღრიცხვის ავტომატური გათვლა თქვენი ტარიფებითა და მარჟით ინდივიდუალური შემუშავებაა, ${ka('development')}, მარშრუტზე კონსიერჟის დამატება კი პილოტის შემდეგ შეიძლება.`],
  q:['Что ИИ делает для туроператора?','What does AI do for a tour operator?','რას აკეთებს AI ტუროპერატორისთვის?'],
  a:['ИИ-ассистент в WhatsApp, Telegram и на сайте собирает бриф туриста: даты, состав группы, бюджет и интересы. Затем он подбирает отели, гидов и транспорт из вашей базы и готовит черновик программы со сметой для менеджера, пока турист ещё на связи. Он отвечает на грузинском, английском, русском и других языках, а во время поездки работает как консьерж на маршруте: напоминает о трансферах и отвечает на вопросы. Цены ассистент берёт только из ваших прайсов и с вашей маржой, программу и оплату подтверждает менеджер. Результат измеряем по времени от запроса до первого предложения.',
   'An AI assistant on WhatsApp, Telegram and your website collects a traveller’s brief: dates, group, budget and interests. It then picks hotels, guides and transport from your database and drafts an itinerary with an estimate for a manager while the traveller is still in the chat. It replies in Georgian, English, Russian and other languages, and during the trip it acts as an on-route concierge, reminding about transfers and answering questions. Prices come only from your rate sheets with your margin, and a manager confirms the programme and payment. We measure the time from enquiry to first proposal.',
   'AI ასისტენტი WhatsApp‑ში, Telegram‑სა და საიტზე ტურისტის ბრიფს აგროვებს: თარიღები, ჯგუფის შემადგენლობა, ბიუჯეტი და ინტერესები. შემდეგ თქვენი ბაზიდან სასტუმროებს, გიდებსა და ტრანსპორტს არჩევს და მენეჯერისთვის პროგრამის მონახაზს ხარჯთაღრიცხვით ამზადებს, სანამ ტურისტი ჯერ კიდევ კავშირზეა. ის ქართულად, ინგლისურად, რუსულად და სხვა ენებზე პასუხობს, მოგზაურობისას კი მარშრუტზე კონსიერჟად მუშაობს: ტრანსფერებზე შეახსენებს და კითხვებს პასუხობს. ფასებს ასისტენტი მხოლოდ თქვენი ფასების სიებიდან და თქვენი მარჟით იღებს, პროგრამასა და გადახდას მენეჯერი ადასტურებს. შედეგს ვზომავთ დროით მოთხოვნიდან პირველ შეთავაზებამდე.']
 },
 'real-estate':{
  cost:[`Пилот для агентства недвижимости стоит от ${ru('implementation')} и идёт 2–4 недели на реальных заявках. Мы загружаем вашу базу объектов из фида или выгрузки CRM, настраиваем вопросы для квалификации и запись на показ. Подготовка данных для договора из сканов документов, с проверкой юристом, — отдельный сценарий, его можно добавить после пилота.`,
   `An estate agency pilot starts at ${en('implementation')} and runs for 2–4 weeks on real enquiries. We load your listings from a feed or a CRM export and set up qualifying questions and viewing bookings. Extracting data from scanned documents for draft contracts, with a lawyer’s review, is a separate workflow that can be added after the pilot.`,
   `უძრავი ქონების სააგენტოს პილოტი ღირს ${ka('implementation')} და 2–4 კვირა გრძელდება რეალურ მოთხოვნებზე. ვტვირთავთ თქვენი ობიექტების ბაზას ფიდიდან ან CRM‑ის ექსპორტიდან, ვაწყობთ კვალიფიკაციის კითხვებსა და ჩვენებაზე ჩაწერას. ხელშეკრულებისთვის მონაცემების მომზადება დოკუმენტების სკანებიდან, იურისტის შემოწმებით, ცალკე სცენარია, მისი დამატება პილოტის შემდეგ შეიძლება.`],
  q:['Что ИИ делает для агентства недвижимости?','What does AI do for an estate agency?','რას აკეთებს AI უძრავი ქონების სააგენტოსთვის?'],
  a:['ИИ принимает заявки из WhatsApp, Telegram, Instagram и с сайта круглосуточно, уточняет бюджет, район, тип объекта и сроки и подбирает варианты из вашей актуальной базы. Он отправляет фото и описание, записывает клиента на показ и создаёт карточку в CRM, например в amoCRM или Bitrix24, с резюме переписки. Голосовые сообщения он расшифровывает, отвечает на грузинском, английском и русском. Снятый с продажи объект ассистент не предложит, а юридические и налоговые вопросы передаёт специалисту. Результат измеряем по времени квалификации и доле обращений, дошедших до показа.',
   'AI takes enquiries from WhatsApp, Telegram, Instagram and your website around the clock, clarifies budget, district, property type and timing, and picks options from your current listings. It sends photos and descriptions, books viewings and creates a record in your CRM, for example amoCRM or Bitrix24, with a summary of the chat. It transcribes voice messages and replies in Georgian, English and Russian. The assistant never offers a property that is off the market, and passes legal and tax questions to a specialist. We measure qualification time and the share of enquiries that reach a viewing.',
   'AI მოთხოვნებს WhatsApp‑იდან, Telegram‑იდან, Instagram‑იდან და საიტიდან დღე‑ღამის განმავლობაში იღებს, აზუსტებს ბიუჯეტს, უბანს, ობიექტის ტიპსა და ვადებს და თქვენი აქტუალური ბაზიდან ვარიანტებს არჩევს. ის აგზავნის ფოტოებსა და აღწერას, კლიენტს ჩვენებაზე წერს და CRM‑ში, მაგალითად amoCRM‑ში ან Bitrix24‑ში, ბარათს მიმოწერის შეჯამებით ქმნის. ხმოვან შეტყობინებებს შიფრავს, პასუხობს ქართულად, ინგლისურად და რუსულად. გაყიდვიდან მოხსნილ ობიექტს ასისტენტი არ შესთავაზებს, იურიდიულ და საგადასახადო კითხვებს კი სპეციალისტს გადასცემს. შედეგს ვზომავთ კვალიფიკაციის დროითა და ჩვენებამდე მისული მიმართვების წილით.']
 },
 developers:{
  cost:[`На лидах с рекламы пилот для застройщика идёт 2–4 недели и стоит от ${ru('implementation')}. В него входят вопросы для квалификации, отправка планировок и цен из ваших материалов проекта и карточка в CRM с тегами. Связка с шахматкой, чтобы бот видел только свободные квартиры, и калькулятор рассрочки по вашим формулам — разработка, от ${ru('development')}.`,
   `A developer pilot runs on ad leads for 2–4 weeks and starts at ${en('implementation')}. It includes qualifying questions, sending floor plans and prices from your project materials, and a tagged CRM record. A link to your inventory system, so the bot sees only available units, and an instalment calculator based on your formulas are custom development, from ${en('development')}.`,
   `დეველოპერის პილოტი ღირს ${ka('implementation')} და 2–4 კვირა გრძელდება რეკლამიდან შემოსულ ლიდებზე. მასში შედის კვალიფიკაციის კითხვები, გეგმარებებისა და ფასების გაგზავნა თქვენი პროექტის მასალებიდან და CRM‑ის ბარათი ტეგებით. კავშირი ბინების ცხრილთან, რომ ბოტმა მხოლოდ თავისუფალი ბინები დაინახოს, და განვადების კალკულატორი თქვენი ფორმულებით ინდივიდუალური შემუშავებაა, ${ka('development')}.`],
  q:['Что ИИ делает для застройщика?','What does AI do for a property developer?','რას აკეთებს AI დეველოპერისთვის?'],
  a:['ИИ отвечает на заявки с рекламы в WhatsApp, Instagram и на сайте сразу, в том числе ночью, на грузинском, английском и русском. Он уточняет бюджет, цель покупки, площадь и срок, отправляет актуальные планировки и цены из шахматки (например, Profitbase или MacroCRM) и передаёт менеджеру тёплого клиента, готового к показу, с карточкой в CRM. Покупателей из-за рубежа ассистент ведёт на их языке. Скидок он не даёт, условия рассрочки не придумывает и одобрение ипотеки не обещает, а нестандартные вопросы передаёт старшему менеджеру. Результат измеряем по времени ответа и доле квалифицированных обращений.',
   'AI replies to ad leads on WhatsApp, Instagram and your website immediately, including at night, in Georgian, English and Russian. It clarifies budget, purpose of purchase, size and timing, sends current floor plans and prices from your inventory system (for example Profitbase or MacroCRM) and hands a warm, viewing-ready buyer to a manager with a CRM record. It serves buyers from abroad in their own language. It never gives discounts, invents instalment terms or promises mortgage approval, and passes non-standard questions to a senior manager. We measure response time and the share of qualified enquiries.',
   'AI რეკლამიდან შემოსულ მოთხოვნებს WhatsApp‑ში, Instagram‑სა და საიტზე მაშინვე პასუხობს, ღამითაც, ქართულად, ინგლისურად და რუსულად. ის აზუსტებს ბიუჯეტს, შეძენის მიზანს, ფართობსა და ვადას, აგზავნის აქტუალურ გეგმარებებსა და ფასებს ბინების ცხრილიდან (მაგალითად, Profitbase‑იდან ან MacroCRM‑იდან) და ჩვენებისთვის მზად მყოფ თბილ კლიენტს მენეჯერს CRM‑ის ბარათით გადასცემს. საზღვარგარეთელ მყიდველებს ასისტენტი მათ ენაზე ემსახურება. ფასდაკლებას არ აძლევს, განვადების პირობებს არ იგონებს და იპოთეკის დამტკიცებას არ ჰპირდება, არასტანდარტულ კითხვებს კი უფროს მენეჯერს გადასცემს. შედეგს ვზომავთ პასუხის დროითა და კვალიფიციური მიმართვების წილით.']
 },
 restaurants:{
  cost:[`ИИ-хостес для ресторана стоит от ${ru('implementation')}, пилот на реальных заявках — 2–4 недели. Для пилота берём одно из двух: заявки на столы, которые подтверждает администратор, или банкетный бриф для менеджера. Проверка посадки прямо в iiko, r_keeper или Poster и приём заказов на доставку с учётом стоп-листа — разработка, от ${ru('development')}.`,
   `An AI host for a restaurant starts at ${en('implementation')}, and a pilot on real requests takes 2–4 weeks. For the pilot we take one of two workflows: table requests confirmed by your staff, or the event brief for the manager. Checking seating directly in iiko, r_keeper or Poster and taking delivery orders that respect the stop list are custom development, from ${en('development')}.`,
   `რესტორნის AI ჰოსტესი ღირს ${ka('implementation')}, პილოტი რეალურ მოთხოვნებზე 2–4 კვირა გრძელდება. პილოტისთვის ორიდან ერთს ვიღებთ: მაგიდების მოთხოვნებს, რომლებსაც ადმინისტრატორი ადასტურებს, ან ბანკეტის ბრიფს მენეჯერისთვის. ადგილების შემოწმება პირდაპირ iiko‑ში, r_keeper‑ში ან Poster‑ში და მიტანის შეკვეთების მიღება სტოპ‑ლისტის გათვალისწინებით ინდივიდუალური შემუშავებაა, ${ka('development')}.`],
  q:['Что ИИ делает для ресторана?','What does AI do for a restaurant?','რას აკეთებს AI რესტორნისთვის?'],
  a:['ИИ-хостес принимает заявки на столы в Instagram, WhatsApp и на сайте круглосуточно, проверяет посадку в вашей системе (например, iiko, r_keeper или Poster) и подтверждает бронь на грузинском, английском или русском. По банкетам он собирает полный бриф для менеджера: дату, число гостей, меню, бюджет и пожелания. Он отвечает о меню, доставке и самовывозе. Блюда из стоп-листа ассистент не предлагает, бронь подтверждает только по данным системы, а нестандартные запросы передаёт администратору. Результат измеряем по времени сбора брифа и полноте заявки.',
   'An AI host takes table requests on Instagram, WhatsApp and your website around the clock, checks seating in your system (for example iiko, r_keeper or Poster) and confirms the booking in Georgian, English or Russian. For events it collects a full brief for the manager: date, number of guests, menu, budget and wishes. It answers questions about the menu, delivery and takeaway. The assistant never offers dishes on the stop list, confirms bookings only from system data and passes non-standard requests to the manager on duty. We measure brief collection time and enquiry completeness.',
   'AI ჰოსტესი მაგიდების მოთხოვნებს Instagram‑ში, WhatsApp‑სა და საიტზე დღე‑ღამის განმავლობაში იღებს, ადგილებს თქვენს სისტემაში ამოწმებს (მაგალითად, iiko‑ში, r_keeper‑ში ან Poster‑ში) და ჯავშანს ქართულად, ინგლისურად ან რუსულად ადასტურებს. ბანკეტებისთვის მენეჯერს სრულ ბრიფს უგროვებს: თარიღი, სტუმრების რაოდენობა, მენიუ, ბიუჯეტი და სურვილები. ის პასუხობს მენიუზე, მიწოდებასა და წაღებაზე. სტოპ‑ლისტის კერძებს ასისტენტი არ სთავაზობს, ჯავშანს მხოლოდ სისტემის მონაცემებით ადასტურებს, არასტანდარტულ მოთხოვნებს კი ადმინისტრატორს გადასცემს. შედეგს ვზომავთ ბრიფის შეგროვების დროითა და მოთხოვნის სისრულით.']
 },
 clinics:{
  cost:[`ИИ-администратор для клиники стоит от ${ru('implementation')}, пилот — 2–4 недели. В пилот входят ответы об услугах, ценах и подготовке к исследованиям, запись через мессенджер и напоминание накануне визита. Запись прямо в свободные слоты вашей МИС — разработка, от ${ru('development')}. Голосового ассистента для звонков обсуждаем отдельно и проверяем его качество на ваших сценариях.`,
   `An AI receptionist for a clinic starts at ${en('implementation')}, with a 2–4 week pilot. The pilot covers answers about services, prices and test preparation, booking requests in a messenger and a reminder the day before the visit. Booking directly into free slots in your clinic system is custom development, from ${en('development')}. A voice assistant for phone calls is discussed separately, and we test its quality on your scenarios.`,
   `კლინიკის AI ადმინისტრატორი ღირს ${ka('implementation')}, პილოტი 2–4 კვირა გრძელდება. პილოტში შედის პასუხები მომსახურებაზე, ფასებსა და გამოკვლევებისთვის მომზადებაზე, ჩაწერა მესენჯერით და შეხსენება ვიზიტის წინა დღეს. ჩაწერა პირდაპირ თქვენი სამედიცინო სისტემის თავისუფალ სლოტებში ინდივიდუალური შემუშავებაა, ${ka('development')}. ზარებისთვის ხმოვან ასისტენტს ცალკე განვიხილავთ და მის ხარისხს თქვენს სცენარებზე ვამოწმებთ.`],
  q:['Что ИИ делает для клиники?','What does AI do for a clinic?','რას აკეთებს AI კლინიკისთვის?'],
  a:['ИИ-администратор отвечает пациентам в WhatsApp, Telegram и на сайте круглосуточно на грузинском, английском и русском. Он рассказывает об услугах, ценах и подготовке к приёму, записывает в свободные слоты вашей медицинской системы (например, Medesk, YCLIENTS или 1С:Медицина) и напоминает о визите накануне. После приёма он спрашивает о самочувствии и просит оставить отзыв. Диагнозов и медицинских советов ассистент не даёт: если пациент описывает симптомы, он переводит диалог на врача или предлагает срочную запись. Медицинские данные обрабатываются по согласованным правилам доступа. Результат измеряем по нагрузке на администратора и времени ответа.',
   'An AI receptionist answers patients on WhatsApp, Telegram and your website around the clock in Georgian, English and Russian. It explains services, prices and how to prepare for a visit, books free slots in your medical system (for example Medesk, YCLIENTS or 1C:Medicine) and sends a reminder the day before. After the visit it asks how the patient feels and requests a review. The assistant never diagnoses or gives medical advice: when a patient describes symptoms, it hands the chat to a doctor or offers an urgent appointment. Medical data is handled under agreed access rules. We measure reception workload and response time.',
   'AI ადმინისტრატორი პაციენტებს WhatsApp‑ში, Telegram‑სა და საიტზე დღე‑ღამის განმავლობაში ქართულად, ინგლისურად და რუსულად პასუხობს. ის ყვება მომსახურებაზე, ფასებსა და ვიზიტისთვის მომზადებაზე, თქვენი სამედიცინო სისტემის თავისუფალ სლოტებში წერს (მაგალითად, Medesk‑ში, YCLIENTS‑ში ან 1C:Medicine‑ში) და ვიზიტს წინა დღეს შეახსენებს. მიღების შემდეგ ექიმის რეკომენდაციებს უგზავნის და შეფასების დატოვებას სთხოვს. დიაგნოზებსა და სამედიცინო რჩევებს ასისტენტი არ იძლევა: თუ პაციენტი სიმპტომებს აღწერს, საუბარს ექიმს გადასცემს ან სასწრაფო ჩაწერას სთავაზობს. სამედიცინო მონაცემები შეთანხმებული წვდომის წესებით მუშავდება. შედეგს ვზომავთ ადმინისტრატორის დატვირთვითა და პასუხის დროით.']
 },
 logistics:{
  cost:[`В логистике для пилота выбираем один поток: распознавание CMR и инвойсов со сверкой веса и количества или ответы клиентам «где мой груз» по данным из таблицы или системы трекинга с API. Пилот идёт 2–4 недели и стоит от ${ru('implementation')}. Запись документов прямо в TMS, 1С или ERP — разработка, от ${ru('development')}.`,
   `In logistics we pick one flow for the pilot: reading CMRs and invoices and cross-checking weight and quantity, or answering customers’ “where is my cargo” from a spreadsheet or a tracking system with an API. The pilot takes 2–4 weeks and starts at ${en('implementation')}. Writing documents directly into your TMS, 1C or ERP is custom development, from ${en('development')}.`,
   `ლოჯისტიკის პილოტი ღირს ${ka('implementation')} და 2–4 კვირა გრძელდება. ვირჩევთ ერთ ნაკადს: CMR‑ებისა და ინვოისების ამოცნობა წონისა და რაოდენობის შედარებით ან კლიენტებისთვის პასუხი „სად არის ჩემი ტვირთი“ ტრეკინგის მონაცემებით. დოკუმენტების პირდაპირ TMS‑ში, 1C‑ში ან ERP‑ში ჩაწერა ინდივიდუალური შემუშავებაა, ${ka('development')}.`],
  q:['Что ИИ делает в логистике?','What does AI do for logistics?','რას აკეთებს AI ლოჯისტიკაში?'],
  a:['ИИ извлекает данные из CMR, инвойсов, пакинг-листов и фото документов от водителей и заносит их в вашу TMS или учётную систему, например в 1С или SAP. Он сверяет документы между собой и подсвечивает расхождения, например вес в инвойсе и в пакинг-листе. Клиентам он отвечает на вопрос «где мой груз» в WhatsApp и Telegram по данным вашей системы, а водителям помогает с документами и маршрутом. Декларации ИИ не отправляет: спорные данные подтверждает сотрудник. Результат измеряем по времени обработки и количеству ручных переносов данных.',
   'AI extracts data from CMRs, invoices, packing lists and drivers’ photos of documents and enters it into your TMS or accounting system, for example 1C or SAP. It cross-checks documents and flags mismatches, such as weight on the invoice versus the packing list. It answers customers’ “where is my cargo” questions on WhatsApp and Telegram from your system, and helps drivers with paperwork and routes. AI does not submit declarations: a staff member confirms disputed data. We measure processing time and the number of manual data transfers.',
   'AI მონაცემებს CMR‑ებიდან, ინვოისებიდან, შეფუთვის სიებიდან და მძღოლების მიერ გადაღებული დოკუმენტების ფოტოებიდან იღებს და თქვენს TMS‑ში ან სააღრიცხვო სისტემაში შეაქვს, მაგალითად 1C‑ში ან SAP‑ში. ის დოკუმენტებს ერთმანეთს ადარებს და შეუსაბამობებს მონიშნავს, მაგალითად წონას ინვოისსა და შეფუთვის სიაში. კლიენტებს კითხვაზე „სად არის ჩემი ტვირთი“ WhatsApp‑სა და Telegram‑ში თქვენი სისტემის მონაცემებით პასუხობს, მძღოლებს კი დოკუმენტებსა და მარშრუტში ეხმარება. დეკლარაციებს AI არ აგზავნის: სადავო მონაცემებს თანამშრომელი ადასტურებს. შედეგს ვზომავთ დამუშავების დროითა და მონაცემების ხელით გადატანის რაოდენობით.']
 },
 manufacturing:{
  cost:[`Ассистент на ваших документах стоит от ${ru('implementation')}, пилот на одном участке — 2–4 недели. Для пилота загружаем документы этого участка, например инструкции по обслуживанию одной линии и коды ошибок, и даём доступ с телефона в цеху. Интеграция с ERP или MES считается разработкой, от ${ru('development')}.`,
   `An assistant on your documents starts at ${en('implementation')}, and a pilot in one area takes 2–4 weeks. For the pilot we load that area’s documents, for example the maintenance manuals and error codes for one line, and give staff access from a phone on the shop floor. ERP or MES integration counts as custom development, from ${en('development')}.`,
   `ასისტენტი თქვენს დოკუმენტებზე ღირს ${ka('implementation')}, პილოტი ერთ უბანზე 2–4 კვირა გრძელდება. პილოტისთვის ამ უბნის დოკუმენტებს ვტვირთავთ, მაგალითად ერთი ხაზის მომსახურების ინსტრუქციებსა და შეცდომის კოდებს, და თანამშრომლებს საამქროში ტელეფონიდან წვდომას ვაძლევთ. ERP‑თან ან MES‑თან ინტეგრაცია ინდივიდუალურ შემუშავებად ითვლება, ${ka('development')}.`],
  q:['Что ИИ делает на производстве?','What does AI do in manufacturing?','რას აკეთებს AI წარმოებაში?'],
  a:['ИИ-ассистент отвечает инженерам, мастерам и операторам по вашим инструкциям, спецификациям, регламентам охраны труда и архиву ремонтов. Каждый ответ он сопровождает ссылкой на конкретный раздел утверждённого документа. Он помогает найти порядок обслуживания оборудования, проверить допуск к работам и подготовить заявку на запчасти или сырьё по данным вашей системы, например SAP или 1С. Доступен он в цеху с телефона или в Microsoft Teams. Решение всегда остаётся за инженером, а вариант размещения, вплоть до серверов на вашей площадке, подбираем под требования к секретности. Результат измеряем по времени поиска и точности найденной информации.',
   'An AI assistant answers engineers, supervisors and operators from your instructions, specifications, safety rules and maintenance archive, and every answer links to the exact section of an approved document. It helps find equipment maintenance procedures, check work permits and prepare requests for spare parts or materials from your system data, for example SAP or 1C. Staff reach it on the shop floor from a phone or in Microsoft Teams. The engineer always makes the decision, and we choose the hosting option, up to servers on your premises, to match your confidentiality requirements. We measure search time and retrieval accuracy.',
   'AI ასისტენტი ინჟინრებს, ოსტატებსა და ოპერატორებს თქვენი ინსტრუქციებით, სპეციფიკაციებით, შრომის უსაფრთხოების წესებითა და რემონტების არქივით პასუხობს. თითოეულ პასუხს დამტკიცებული დოკუმენტის კონკრეტულ ნაწილზე ბმულით ახლავს. ის ეხმარება აღჭურვილობის მომსახურების წესის პოვნაში, სამუშაოებზე დაშვების შემოწმებასა და სათადარიგო ნაწილების ან ნედლეულის მოთხოვნის მომზადებაში თქვენი სისტემის მონაცემებით, მაგალითად SAP‑იდან ან 1C‑იდან. საამქროში ის ტელეფონიდან ან Microsoft Teams‑ში ხელმისაწვდომია. გადაწყვეტილება ყოველთვის ინჟინერთან რჩება, განთავსების ვარიანტს კი, თქვენს ტერიტორიაზე სერვერების ჩათვლით, საიდუმლოების მოთხოვნებზე ვარჩევთ. შედეგს ვზომავთ ძიების დროითა და ნაპოვნი ინფორმაციის სიზუსტით.']
 },
 services:{
  cost:[`Пилот для агентства или консалтинга стоит от ${ru('implementation')} и идёт 2–4 недели на одном процессе: протоколы и задачи после созвонов или черновики КП по вашим шаблонам. Задачи создаются в трекере, которым вы уже пользуетесь. Если команде сначала нужно научиться работать с ИИ на своих документах, обучение стоит от ${ru('training')}.`,
   `An agency or consultancy pilot starts at ${en('implementation')} and takes 2–4 weeks on one workflow: minutes and tasks after calls, or draft proposals from your templates. Tasks are created in the tracker you already use. If the team first needs to learn to work with AI on its own documents, training starts at ${en('training')}.`,
   `სააგენტოს ან საკონსულტაციო კომპანიის პილოტი ღირს ${ka('implementation')} და 2–4 კვირა გრძელდება ერთ პროცესზე: ოქმები და ამოცანები ზარების შემდეგ ან შეთავაზებების მონახაზები თქვენი შაბლონებით. ამოცანები იმ ტრეკერში იქმნება, რომელსაც უკვე იყენებთ. თუ გუნდს ჯერ საკუთარ დოკუმენტებზე AI‑ით მუშაობის სწავლა სჭირდება, სწავლება ღირს ${ka('training')}.`],
  q:['Что ИИ делает для агентства или консалтинга?','What does AI do for an agency or consultancy?','რას აკეთებს AI სააგენტოსთვის ან საკონსულტაციო კომპანიისთვის?'],
  a:['ИИ превращает запись звонка с клиентом в протокол, бриф и задачи для команды в вашем трекере, например Jira, Asana, Notion или Bitrix24. По брифу он готовит черновик коммерческого предложения и договора на основе ваших шаблонов и прошлых проектов, а база знаний компании отвечает сотрудникам по кейсам, ценам и регламентам. Так команда тратит меньше неоплачиваемых часов на пресейл. Конфиденциальную информацию клиентов обрабатываем по согласованным правилам доступа и размещения, финальную вычитку документов делает специалист. Результат измеряем по времени подготовки предложения и числу уточнений.',
   'AI turns a recording of a client call into minutes, a brief and tasks for the team in your tracker, for example Jira, Asana, Notion or Bitrix24. From the brief it drafts a proposal and contract using your templates and past projects, and a company knowledge base answers staff questions about cases, rates and procedures. The team spends fewer unpaid hours on presales. Client confidential information is handled under agreed access and hosting rules, and a specialist does the final review of documents. We measure proposal preparation time and the number of clarification rounds.',
   'AI კლიენტთან ზარის ჩანაწერს ოქმად, ბრიფად და გუნდის ამოცანებად აქცევს თქვენს ტრეკერში, მაგალითად Jira‑ში, Asana‑ში, Notion‑სა ან Bitrix24‑ში. ბრიფით ის კომერციული შეთავაზებისა და ხელშეკრულების მონახაზს თქვენი შაბლონებითა და წინა პროექტებით ამზადებს, კომპანიის ცოდნის ბაზა კი თანამშრომლებს ქეისებზე, ფასებსა და წესებზე პასუხობს. ასე გუნდი პრესეილზე ნაკლებ აუნაზღაურებელ საათს ხარჯავს. კლიენტების კონფიდენციალურ ინფორმაციას შეთანხმებული წვდომისა და განთავსების წესებით ვამუშავებთ, დოკუმენტების საბოლოო შემოწმებას სპეციალისტი აკეთებს. შედეგს ვზომავთ შეთავაზების მომზადების დროითა და დაზუსტებების რაოდენობით.']
 },
 education:{
  cost:[`Для школы или курсов пилот идёт 2–4 недели и стоит от ${ru('implementation')}. В него входят ответы о программах, ценах и рассрочке по вашей оферте и запись на пробный урок с передачей заявки в CRM. Бот-куратора для текущих студентов и проверку заданий можно добавить после пилота.`,
   `For a school or course provider, the pilot takes 2–4 weeks and starts at ${en('implementation')}. It covers answers about programmes, prices and instalments from your offer, and trial-lesson booking with the application passed to your CRM. A curator bot for current students and assignment checking can be added after the pilot.`,
   `სკოლის ან კურსების პილოტი ღირს ${ka('implementation')} და 2–4 კვირა გრძელდება, მას მიღების სეზონში ვატარებთ. მასში შედის პასუხები პროგრამებზე, ფასებსა და განვადებაზე თქვენი ოფერტით და საცდელ გაკვეთილზე ჩაწერა მოთხოვნის CRM‑ში გადაცემით. კურატორი‑ბოტის დამატება მიმდინარე სტუდენტებისთვის და დავალებების შემოწმება მიღების შემდეგ შეიძლება.`],
  q:['Что ИИ делает для школы или курсов?','What does AI do for a school or course provider?','რას აკეთებს AI სკოლისთვის ან კურსებისთვის?'],
  a:['ИИ-ассистент в Telegram, WhatsApp, Instagram и на сайте помогает выбрать программу и тариф, отвечает о расписании, ценах и условиях договора и записывает на пробное занятие на грузинском, английском или русском. Заявки он передаёт в CRM, например в amoCRM или AlfaCRM. Студентам бот-куратор напоминает о дедлайнах и отвечает на типовые вопросы по курсу, а преподавателю помогает проверять задания по вашим критериям. Спорные оценки остаются за преподавателем. Ассистент отвечает только по вашим программам и договору и не обещает того, чего нет в оферте. Результат измеряем по времени ответа и полноте заявок на обучение.',
   'An AI assistant on Telegram, WhatsApp, Instagram and your website helps prospective students choose a programme and plan, answers questions about schedules, prices and contract terms, and books trial lessons in Georgian, English or Russian. It passes applications to your CRM, for example amoCRM or AlfaCRM. For students, a curator bot reminds them about deadlines and answers routine course questions, and for teachers it helps check assignments against your criteria, with disputed grades left to the teacher. The assistant answers only from your programmes and contract and never promises what is not in the offer. We measure response time and application completeness.',
   'AI ასისტენტი Telegram‑ში, WhatsApp‑ში, Instagram‑სა და საიტზე პროგრამისა და ტარიფის არჩევაში ეხმარება, პასუხობს განრიგზე, ფასებსა და ხელშეკრულების პირობებზე და საცდელ გაკვეთილზე წერს ქართულად, ინგლისურად ან რუსულად. მოთხოვნებს CRM‑ში გადასცემს, მაგალითად amoCRM‑ში ან AlfaCRM‑ში. სტუდენტებს ბოტი‑კურატორი ვადებს შეახსენებს და კურსზე ტიპურ კითხვებს პასუხობს, მასწავლებელს კი დავალებების თქვენი კრიტერიუმებით შემოწმებაში ეხმარება. სადავო შეფასებები მასწავლებელთან რჩება. ასისტენტი მხოლოდ თქვენი პროგრამებითა და ხელშეკრულებით პასუხობს და არ ჰპირდება იმას, რაც ოფერტაში არ არის. შედეგს ვზომავთ პასუხის დროითა და სწავლის მოთხოვნების სისრულით.']
 },
};
